head.script:
scwin.dataListId = "dataList1";
scwin.dataListId2 = "dataList2";
scwin.gridViewId = "gridView1";
scwin.gridViewId2 = "gridView2";
scwin.extraColNum = 5 + 6;
scwin.extraColNum2 = 5;
scwin.oneDayCol = ['pdiaDvChar', 'ndDno', 'totWrkTnum', 'pdiaNoView', 'repTrn1No', 'repTrn2No', 'pjt2PdiaNo', 'gwkTm', 'loiwTm']
scwin.focusMergeUnitStart = 0; // 그룹 포커스 기능을 적용하지 않을 왼쪽 컬럼 개수
scwin.focusMergeUnitEnd = 0; // 그룹 포커스 기능을 적용하지 않을 오른쪽 컬럼 개수
scwin.hybridColNum = 96; // 버퍼 컬럼 수. 기본값은 10. 현재 화면에 보이는 컬럼 수에 버퍼 컬럼을 더한 만큼만 실제 DOM으로 렌더링

scwin.onpageload = function() {
	scwin.createDataList1();
	scwin.createDataList2();
	scwin.loadData();
	scwin.createGridView1_detail();
	scwin.createGridView2_detail();
};

scwin.createDataList1 = function() {
	if ($p.getComponentById(scwin.dataListId)) {
		$p.data.remove(scwin.dataListId);
	}
	var dayCnt = scwin.getDaysInCurrentMonth();
	var colInfo = [{
		"dataType": "text",
		"id": "diaPosiCd"
	}, {
		"dataType": "text",
		"id": "empNm"
	}, {
		"dataType": "text",
		"id": "epno"
	}, {
		"dataType": "number",
		"id": "holidayGwkTm"
	}, {
		"dataType": "number",
		"id": "totalGwkTm"
	}, {
		"dataType": "text",
		"id": "b_dynamic2"
	}, {
		"dataType": "text",
		"id": "b_dynamic3"
	}, {
		"dataType": "text",
		"id": "b_dynamic4"
	}, {
		"dataType": "text",
		"id": "b_dynamic6"
	}, {
		"dataType": "text",
		"id": "b_dynamic7"
	}, {
		"dataType": "text",
		"id": "b_dynamic8"
	}];
	for (var i = 1; i <= dayCnt; i++) {
		for (var j = 0; j < scwin.oneDayCol.length; j++) {
			colInfo.push({
				"dataType": "text",
				"id": i + "_" + scwin.oneDayCol[j]
			})
		}
	}
	var opt = {
		"type": "dataList",
		"id": scwin.dataListId,
		"option": {
			"baseNode": "list",
			"repeatNode": "map"
		},
		"columnInfo": colInfo
	};
	$p.data.create(opt);
}

scwin.createDataList2 = function() {
	if ($p.getComponentById(scwin.dataListId2)) {
		$p.data.remove(scwin.dataListId2);
	}
	var dayCnt = scwin.getDaysInCurrentMonth();
	var colInfo = [{
		"dataType": "text",
		"id": "diaPosiCd"
	}, {
		"dataType": "text",
		"id": "empNm"
	}, {
		"dataType": "text",
		"id": "epno"
	}, {
		"dataType": "number",
		"id": "holidayGwkTm"
	}, {
		"dataType": "number",
		"id": "totalGwkTm"
	}];
	for (var i = 1; i <= dayCnt; i++) {
		for (var j = 0; j < scwin.oneDayCol.length; j++) {
			colInfo.push({
				"dataType": "text",
				"id": i + "_" + scwin.oneDayCol[j]
			})
		}
	}
	var opt = {
		"type": "dataList",
		"id": scwin.dataListId2,
		"option": {
			"baseNode": "list",
			"repeatNode": "map"
		},
		"columnInfo": colInfo
	};
	$p.data.create(opt);
}

scwin.loadData = function() {
	var url = WebSquare.core.getURL("/data/gridView_multiRow_WAEA-451_(WSQ-6110).txt");
	fetch(url).then(function(resolve, reject) {
		return resolve.text();
	}).then(function(resolve, reject) {
		var dataArr = JSON.parse(resolve);
		var dataListObj = $p.getComponentById(scwin.dataListId);
		dataListObj.setData(dataArr);

		var dataListObj2 = $p.getComponentById(scwin.dataListId2);
		var rowCnt = dataListObj.getRowCount();
		dataListObj2.setBroadcast(false);
		for (var i = 0; i < rowCnt; i++) {
			dataListObj2.insertRow();
		}
		dataListObj2.setBroadcast(true, true);
	})
}

scwin.getCommonGridOptions = function() {
	return ' rowNumVisible="true" rowNumHeaderValue="No." rowMouseOver="false" drawTypeX="hybrid" fixedColumnScrollHidden="true" fixedColumnNoMove="true" useShiftKey="true" ctrlShiftKey="true" oddEvenColorDisplay="false" focusMerge="true" dataDragDropCell="true" dataDragScrollFix="true" showLastRow="true" focusMergeUnitStart="' + scwin.focusMergeUnitStart + '" focusMergeUnitEnd="' + scwin.focusMergeUnitEnd + '" hybridColNum="' + scwin.hybridColNum + '"' + ' noSelect="true" applyAllColumnStyle="true"';
}

scwin.createGridView1_detail = function() {
	var dataListObj = $p.getComponentById(scwin.dataListId);
	var row = 72;
	var col = dataListObj.getColumnCount();
	var totalCol = col - scwin.extraColNum;
	var totalHeaderCol = totalCol / scwin.oneDayCol.length;
	var oneBodyCol = totalHeaderCol * 3;
	var gridColWidth = 70;
	var dayStyle = "";
	var gridXML = [];
	gridXML.push('<w2:gridView xmlns="http://www.w3.org/1999/xhtml" xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" id="' + "gridView1" + '" rowNumWidth="60" style="height:429px;" dataList="data:dataList1" fixedColumn="1" fixedRightColumn="2" readOnly="true" contextMenu="true" focusMergeUnit="3,3" dragEndFunction="scwin.gridView1_dragEndFunction" ev:ondatadragstart="scwin.gridView1_ondatadragstart" ev:onscrollx="scwin.gridView1_onscrollx" ev:onscrolly="scwin.gridView1_onscrolly"' + scwin.getCommonGridOptions() + '>');
	gridXML.push('<w2:caption style="" id="caption1" value="this is a grid caption."/>');
	gridXML.push('<w2:header style="background-color:#e4e7eb;" id="header1">');
	gridXML.push('<w2:row style="" id="row1">');
	gridXML.push('<w2:column width="70" fixColumnWidth="true" inputType="text" style="background-color:#e4e7eb;" id="columnEmpInfo" value="승무원"/>');
	for (var i = 0; i < totalHeaderCol; i++) {
		var dayStyle = scwin.styleTest(i);
		var hiddenStyle = "";
		if (i % 3 === 0) {
			hiddenStyle = ' hidden="true"';
		}
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="background-color:#e4e7eb;' + dayStyle + '" id="column' + i + '" value="' + (i + 1) + '" displayMode="label" colSpan="3"' + hiddenStyle + '/>');
	}
	gridXML.push('<w2:column width="70" inputType="text" style="background-color:#e4e7eb;" id="columnOffdDdFlg" value="휴일" displayMode="label" />');
	gridXML.push('<w2:column width="70" inputType="text" style="background-color:#e4e7eb;" id="columnGwkTm" value="근무시간" displayMode="label" />');
	gridXML.push('</w2:row>');
	gridXML.push('</w2:header>');
	gridXML.push('<w2:gBody style="" id="gBody1">');
	gridXML.push('<w2:row style="" id="rowB1">');
	gridXML.push('<w2:column width="70" inputType="text" style="" id="epno" value="" displayMode="label"/>');
	for (var i = 0; i < oneBodyCol; i++) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3);
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
		var styleStr = "";
		if (i % 2 === 1) {
			styleStr = ' style="font-weight:bold;color:red;font-size:14px;"'
		}
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text"' + styleStr + ' id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('<w2:column rowSpan="3" width="70" inputType="text" style="background-color : #ADD8E6;" id="holidayGwkTm" displayMode="label"/>');
	gridXML.push('<w2:column rowSpan="3" width="70" inputType="text" style="background-color : #ADD8E6;" id="totalGwkTm" value="" displayMode="label" customFormatter="scwin.customFormatterTotalGwkTm"/>');
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row style="" id="rowB2">');
	gridXML.push('<w2:column width="70" inputType="text" style="" id="empNm" value="" displayMode="label"/>');
	for (var i = 0; i < oneBodyCol; i++) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 3;
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
		var styleStr = "";
		if (i % 2 === 0) {
			styleStr = ' style="font-weight:bold;color:green;font-size:14px;"'
		}
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text"' + styleStr + ' id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row style="" id="rowB3">');
	gridXML.push('<w2:column width="70" inputType="text" style="" id="diaPosiCd" value="" displayMode="label"/>');
	for (var i = 0; i < oneBodyCol; i++) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 6;
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
		var styleStr = "";
		if (i % 5 === 2) {
			styleStr = ' style="font-weight:bold;color:blue;font-size:14px;"'
		}
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text"' + styleStr + ' id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('</w2:gBody>');
	gridXML.push('<w2:footer id="footer1" style="">');
	gridXML.push('<w2:row id="row5" style="">');
	gridXML.push('<w2:column displayMode="label" id="ft1_epno" inputType="text" style="" value="" width="70"/>');
	for (var i = 0; i < totalHeaderCol; i++) {
		var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum);
		var styleStr = ' style="' + scwin.styleTest(i, "background-color") + '"';
		gridXML.push('<w2:column colSpan="3" width="' + gridColWidth + '" inputType="expression" id="ft1_' + dateKey + '"' + styleStr + ' value="" displayMode="label" expression="custom(scwin.gridView1_footerCustomFormatter, &quot;' + dateKey + '&quot;)"/>');
	}
	gridXML.push('<w2:column width="70" inputType="expression" style="" id="ft1_holidayGwkTm" value="" displayMode="label" rowSpan="2" expression="SUM(&quot;' + "holidayGwkTm" + '&quot;)"/>');
	gridXML.push('<w2:column width="70" inputType="expression" style="" id="ft1_totalGwkTm" value="" displayMode="label" rowSpan="2" expression="scwin.customFormatterTotalGwkTm(SUM(&quot;' + "totalGwkTm" + '&quot;))"/>');
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row id="row6" style="">');
	gridXML.push('<w2:column displayMode="label" id="ft2_epno" inputType="text" style="" value="" width="70"/>');
	for (var i = 0; i < totalHeaderCol; i++) {
		var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum);
		gridXML.push('<w2:column colSpan="3" width="' + gridColWidth + '" inputType="expression" style="" id="ft2_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView1_footerCustomFormatter2, &quot;' + dateKey + '&quot;)"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('</w2:footer>');
	gridXML.push('</w2:gridView>');
	var gridStr = gridXML.join(" ");
	gridView1.setGridStyle(gridStr);
}

