scwin.createGridView2_simple = function() {
	var dataListObj = $p.getComponentById(scwin.dataListId2);
	var row = 72;
	var col = dataListObj.getColumnCount();
	var totalCol = col - scwin.extraColNum2;
	var totalHeaderCol = totalCol / scwin.oneDayCol.length;
	var oneBodyCol = totalHeaderCol * 3;
	var gridColWidth = 70;
	var dayStyle = "";
	var gridXML = [];
	gridXML.push('<w2:gridView xmlns="http://www.w3.org/1999/xhtml" xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" id="' + "gridView2" + '" rowNumWidth="129" style="height:429px;" dataList="data:dataList2" fixedColumn="0" fixedRightColumn="0" focusMergeUnit="3,1" dragEndFunction="scwin.gridView2_dragEndFunction" ev:onscrollx="scwin.gridView2_onscrollx" ev:onscrolly="scwin.gridView2_onscrolly"' + scwin.getCommonGridOptions() + '>');
	gridXML.push('<w2:caption style="" id="caption1" value="this is a grid caption."/>');
	gridXML.push('<w2:header style="" id="header1">');
	gridXML.push('<w2:row style="" id="row1">');
	for (var i = 0; i < totalHeaderCol; i++) {
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="background-color:#e4e7eb;' + dayStyle + '" id="column' + i + '" value="' + (i + 1) + '" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('</w2:header>');
	gridXML.push('<w2:gBody style="" id="gBody1">');
	gridXML.push('<w2:row style="" id="rowB1">');
	for (var i = 0; i < oneBodyCol; i += 3) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3);
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum2);
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row style="" id="rowB2">');
	for (var i = 0; i < oneBodyCol; i += 3) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 3;
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum2);
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row style="" id="rowB3">');
	for (var i = 0; i < oneBodyCol; i += 3) {
		var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 6;
		var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum2);
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('</w2:gBody>');
	gridXML.push('<w2:footer id="footer1" style="">');
	gridXML.push('<w2:row id="row5" style="">');
	for (var i = 0; i < totalHeaderCol; i++) {
		var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum2);
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="expression" style="" id="ft1_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView2_footerCustomFormatter, &quot;' + dateKey + '&quot;)"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('<w2:row id="row6" style="">');
	for (var i = 0; i < totalHeaderCol; i++) {
		var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum2);
		gridXML.push('<w2:column width="' + gridColWidth + '" inputType="expression" style="" id="ft2_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView2_footerCustomFormatter2, &quot;' + dateKey + '&quot;)"/>');
	}
	gridXML.push('</w2:row>');
	gridXML.push('</w2:footer>');
	gridXML.push('</w2:gridView>');
	var gridStr = gridXML.join(" ");
	gridView2.setGridStyle(gridStr);
}

