scwin.convertCellDataArray = function(fromArr, dataList) {
	var ret = [];
	var hash = {};
	for (var i = 0; i < fromArr.length; i++) {
		var colId = fromArr[i].colId;
		var colIdx = colId.slice(0, colId.indexOf("_"));
		hash[fromArr[i].rowIndex + "_" + colIdx] = true;
	}
	for (var item in hash) {
		var info = item.split("_");
		var rowIndex = Number(info[0]);
		var colIdx = info[1];
		for (var j = 0; j < scwin.oneDayCol.length; j++) {
			var colId = colIdx + "_" + scwin.oneDayCol[j];
			ret.push({
				"rowIndex": rowIndex,
				"colId": colId,
				"data": dataList.getCellData(rowIndex, colId)
			})
		}
	}
	return ret;
}


scwin.styleTest = function(idx, style) {
	var colorNames = [
		"red", "blue", "lime", "yellow", "magenta", "cyan", "orange", "purple",
		"springgreen", "deepskyblue", "darkorange", "mediumvioletred", "forestgreen",
		"gold", "crimson", "mediumblue", "chartreuse", "orchid", "teal", "indigo",
		"aquamarine", "tomato", "dodgerblue", "olivedrab", "slateblue", "hotpink",
		"mediumseagreen", "peru", "darkturquoise", "palevioletred", "mediumslateblue", "deeppink"
	];
	var rIdx = idx % colorNames.length;
	if (!style) {
		style = "color";
	}
	var styleStr = style + ":" + colorNames[rIdx] + ";";
	return styleStr;
}

